def sales_to_orders(apps, schema_editor):
    Sale, Order, OrderLine = (apps.get_model("sales", name) for name in ("Sale", "Order", "OrderLine"))
    sales = list(Sale.objects.order_by("id"))
    orders = Order.objects.bulk_create(
        Order(external_id=sale.external_id, status="completed", ordered_at=sale.sold_at) for sale in sales
    )
    OrderLine.objects.bulk_create(
        OrderLine(order=order, menu_item_id=sale.menu_item_id, quantity=sale.quantity, status="fulfilled")
        for sale, order in zip(sales, orders)
    )


def orders_to_sales(apps, schema_editor):
    """Only orders with one line and no add-ons fit a Sale; every other order is dropped on reverse."""
    Sale, OrderLine = apps.get_model("sales", "Sale"), apps.get_model("sales", "OrderLine")
    for line in _single_lines(OrderLine):
        sale = Sale.objects.create(
            external_id=line.order.external_id, menu_item_id=line.menu_item_id, quantity=line.quantity
        )
        Sale.objects.filter(pk=sale.pk).update(sold_at=line.order.ordered_at)


def _single_lines(OrderLine):
    return (
        OrderLine.objects.select_related("order")
        .annotate(lines=Count("order__lines", distinct=True), extras=Count("add_ons", distinct=True))
        .filter(lines=1, extras=0)
        .order_by("id")
    )


